package com.club.service;
import com.club.dto.*; import com.club.entity.*; import com.club.exception.BusinessException; import com.club.repository.PersonaRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Set;
@Service @RequiredArgsConstructor public class ImagenService {
 private static final Set<String> TIPOS=Set.of("image/jpeg","image/png","image/webp"); private final PersonaRepository personaRepository;
 @Transactional public void guardarEnPersona(String personaId,ImagenUploadDTO dto){Persona p=personaRepository.findById(personaId).orElseThrow(()->new BusinessException("Persona no encontrada."));if(dto==null||dto.contenido()==null||dto.contenido().length==0)throw new BusinessException("Debe seleccionar una imagen.");if(!TIPOS.contains(dto.mime()))throw new BusinessException("Solo se permiten imágenes JPG, PNG o WEBP.");if(dto.contenido().length>5*1024*1024)throw new BusinessException("La imagen no puede superar los 5 MB.");p.setImagen(new Imagen(dto.nombre(),dto.mime(),dto.contenido()));personaRepository.save(p);}
 @Transactional public void eliminarDePersona(String personaId){Persona p=personaRepository.findById(personaId).orElseThrow(()->new BusinessException("Persona no encontrada."));if(p.getImagen()!=null)p.getImagen().setEliminado(true);}
 @Transactional(readOnly=true) public ImagenResponse obtener(String personaId){Persona p=personaRepository.findById(personaId).orElseThrow(()->new BusinessException("Persona no encontrada."));Imagen i=p.getImagen();if(i==null||i.isEliminado())throw new BusinessException("La persona no tiene imagen.");return new ImagenResponse(i.getId(),i.getNombre(),i.getMime(),i.getContenido());}
}
